def calculate_max_servings(n: int, q: List[int], a: List[int], b: List[int]) -> int:
    max_servings = 0
    for x in range(max(q) // min(a) + 1):
        y = float('inf')
        for i in range(n):
            if q[i] < x * a[i]:
                y = -float('inf')
                break
            if b[i] > 0:
                y = min(y, (q[i] - x * a[i]) // b[i])
        max_servings = max(max_servings, x + y)
    return max_servings
